create table if not exists users(id serial primary key,username text unique not null,name text not null,role text not null check(role in('admin','accountant')),password_hash text not null,fails int not null default 0,locked_until timestamptz);
create table if not exists categories(id serial primary key,name text unique not null,sub text not null default '',image text not null default '/assets/hardware.svg',archived bool not null default false);
create table if not exists units(id serial primary key,name text unique not null,archived bool not null default false);
create table if not exists products(id serial primary key,code text unique not null,name text not null,category_id int not null references categories,unit_id int not null references units,price bigint not null default 0,description text not null default '',image_url text,tag text,show_on_web bool not null default true,archived bool not null default false);
create table if not exists customers(id serial primary key,name text not null,phone text not null default '',address text not null default '',tax_code text not null default '',note text not null default '',opening_balance bigint not null default 0,is_retail bool not null default false,archived bool not null default false);
create unique index if not exists one_retail on customers(is_retail) where is_retail;
create table if not exists invoices(id serial primary key,number text unique,customer_id int not null references customers,date date not null default current_date,status text not null default 'draft' check(status in('draft','issued','cancelled')),discount bigint not null default 0,vat_percent numeric(5,2) not null default 0,prepaid bigint not null default 0,note text not null default '',cancel_reason text,created_by int references users,created_at timestamptz not null default now());
create table if not exists invoice_lines(id serial primary key,invoice_id int not null references invoices on delete cascade,pos int not null,product_id int references products,name text not null,unit text not null default '',qty numeric(14,3) not null,price bigint not null,discount_percent numeric(5,2) not null default 0);
create table if not exists payments(id serial primary key,customer_id int not null references customers,invoice_id int references invoices,date date not null default current_date,amount bigint not null check(amount>0),method text not null default 'Tiền mặt',note text not null default '',created_by int references users,created_at timestamptz not null default now());
create table if not exists invoice_counters(year int primary key,last int not null);
create table if not exists settings(key text primary key,value text not null default '');
